spCargo_Listar	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `spCargo_Listar`()\nBEGIN\n\n    SELECT idCargo, Nome, Descricao, fAtivo\n\n    FROM Cargo\n\n    WHERE fAtivo = 1\n\n    ORDER BY idCargo;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
